set
  title = 'Stage Management',
  goal = 'Stage Management',
  summary = 'This course trains students to coordinate rehearsals and performances with artistic sensitivity, technical fluency, ethical judgment, and professional calm. Students build a working prompt book, practice stage management paperwork, document blocking, support auditions and rehearsals, call cues, manage technical and dress rehearsals, and respond to realistic production scenarios involving safety, access, labor standards, conflict, and show maintenance.',
  data = $stmgjson${"slug": "stage-management", "title": "Stage Management", "description": "This course trains students to coordinate rehearsals and performances with artistic sensitivity, technical fluency, ethical judgment, and professional calm. Students build a working prompt book, practice stage management paperwork, document blocking, support auditions and rehearsals, call cues, manage technical and dress rehearsals, and respond to realistic production scenarios involving safety, access, labor standards, conflict, and show maintenance.", "topics": [{"id": "814a4eac-f47d-4114-8d53-8ee702f8ce8b", "type": "topic", "title": "The Stage Manager's Role", "description": "This topic frames stage management as an artistic, logistical, ethical, and relational leadership practice. Students learn where authority comes from, where it stops, and how the stage manager protects the production process without taking over the creative process.", "children": [{"id": "95db7d62-23ff-4d1f-8eaf-f55192ae1e49", "type": "subtopic", "title": "Core responsibilities", "children": [{"id": "a08cd802-1242-4bd6-93fb-b1e7921e65c7", "type": "concept", "title": "Rehearsal room preparation"}, {"id": "d573c82d-c6f2-4ec9-bd10-b4cc861e06fa", "type": "concept", "title": "Information tracking"}, {"id": "cd9623f6-215c-4fe2-a3ae-436347fa1bef", "type": "concept", "title": "Production communication"}, {"id": "0e97f9b7-74ca-460f-b72a-893bff783ee8", "type": "concept", "title": "Show maintenance"}], "description": "Why learn it: Students identify what the stage manager owns before rehearsal, during rehearsal, in technical rehearsals, and during the run."}, {"id": "d57d7308-c009-4fa0-8cde-79e8e8dad3df", "type": "subtopic", "title": "Leadership without authorship", "children": [{"id": "68096938-111e-4ea9-aad5-3a688525df9c", "type": "concept", "title": "Facilitation vs. control"}, {"id": "680a14ea-6cda-4993-b3c7-3aef91c2fa22", "type": "concept", "title": "Neutral language"}, {"id": "8468b030-05a4-4eff-80b6-3e86e125f8c2", "type": "concept", "title": "Boundary setting"}, {"id": "0be7c5bb-9b10-4711-9f7f-ffe36d5c4dd0", "type": "concept", "title": "Escalation paths"}], "description": "Why learn it: The point is to practice leadership that serves the director's vision, the ensemble's process, and the production's practical needs."}, {"id": "9125e956-0235-4750-8e2d-a0316791cf02", "type": "subtopic", "title": "Professional identity", "children": [{"id": "35c47a41-4195-466d-aeda-a08c19dea5aa", "type": "concept", "title": "Punctuality"}, {"id": "d5403862-bfd7-460b-a321-06e819a79612", "type": "concept", "title": "Confidentiality"}, {"id": "00c9da06-5631-4a37-844d-f7df4940120f", "type": "concept", "title": "Consistency"}, {"id": "2cd5ae2e-2e03-4798-a741-6945f06cf427", "type": "concept", "title": "Documentation habits"}], "description": "Why learn it: Students connect classroom habits to professional expectations so their work reads as reliable, calm, and clear."}]}, {"id": "92897fbd-bc7e-4eed-9eb5-e9ccd9a1ab8d", "type": "topic", "title": "Production Structures and Collaboration", "description": "Stage managers must understand the full production ecosystem. This section builds fluency in who does what, how decisions move, and how a stage manager coordinates across artistic, technical, administrative, and front-of-house teams.", "children": [{"id": "bfc31d24-7eed-4736-9868-c1e582ef12ce", "type": "subtopic", "title": "Production team roles", "children": [{"id": "26d1430e-caad-4210-b40b-75120a62f823", "type": "concept", "title": "Reporting lines"}, {"id": "ee4b062f-df6d-4ccf-b161-e879e8f66bbf", "type": "concept", "title": "Design meetings"}, {"id": "f2e572a8-65ee-400c-b1c4-a29ecc6c4500", "type": "concept", "title": "Departmental vocabulary"}, {"id": "24c80eb4-9bff-4398-a71b-eb9cc95b778b", "type": "concept", "title": "Role boundaries"}], "description": "Why learn it: Students learn the responsibilities and decision rights of directors, designers, production managers, technical directors, department heads, performers, and crew."}, {"id": "99877c45-27fd-4d6d-aa80-16b73744d2db", "type": "subtopic", "title": "Production calendar logic", "children": [{"id": "51e82fa7-f7cb-410f-a055-845e4fe89972", "type": "concept", "title": "Milestones"}, {"id": "0a43aca5-668e-4647-afa4-05acd1eb84f9", "type": "concept", "title": "Critical path"}, {"id": "a2294ddc-ea24-41ba-a3c7-842339e9f6c8", "type": "concept", "title": "Deadline dependencies"}, {"id": "2b8227af-467d-4fa0-ab13-d15ae1d29e88", "type": "concept", "title": "Conflict windows"}], "description": "Why learn it: Students learn how institutional calendars shape rehearsal schedules, design deadlines, shop builds, tech, previews, opening, and strike."}, {"id": "77a48ef5-b9f8-4080-8d65-7cb3e36d154d", "type": "subtopic", "title": "Meeting practice", "children": [{"id": "b39b9afe-b05d-44e8-b4e7-b6df5bf25d69", "type": "concept", "title": "Agendas"}, {"id": "2d48d908-7846-496e-83af-bfc0c4f97a3a", "type": "concept", "title": "Minutes"}, {"id": "03be1718-6d39-48a2-9d34-27ad8e3ccfb4", "type": "concept", "title": "Action items"}, {"id": "8a0c90eb-9cd1-410d-a56b-66c268a2883c", "type": "concept", "title": "Follow-up tracking"}], "description": "Why learn it: The goal is to make meetings efficient, inclusive, and actionable rather than merely informational."}]}, {"id": "d3bfb64b-f07b-4333-af25-db50cb57bc21", "type": "topic", "title": "Auditions and Casting Support", "description": "This topic prepares stage managers to support auditions fairly and efficiently while respecting artistic authority and performer dignity. Students learn the paperwork, timing, room flow, and communication expected before casting is finalized.", "children": [{"id": "19776284-24c1-4aff-a5e1-5f5e2e12bec1", "type": "subtopic", "title": "Audition logistics", "children": [{"id": "95267f10-3571-4c10-8c76-fdfba50bd225", "type": "concept", "title": "Room setup"}, {"id": "1f4132fd-0539-4772-9f45-402ddcc6af51", "type": "concept", "title": "Check-in systems"}, {"id": "1b166223-8d9c-47fb-bcdd-8fb6dd556072", "type": "concept", "title": "Sides and forms"}, {"id": "b96aa309-800a-433f-977e-00cc99d1d186", "type": "concept", "title": "Accessibility needs"}], "description": "Why learn it: Students plan audition spaces, materials, sign-in flow, timekeeping, and communication with auditioners."}, {"id": "855bdc4b-27b2-461f-9e70-c3d6d7bdb09d", "type": "subtopic", "title": "Casting documentation", "children": [{"id": "f2d7c46d-8f90-4664-a781-62fc270e1216", "type": "concept", "title": "Audition forms"}, {"id": "d4258076-1f28-4cba-8f38-a032949b172d", "type": "concept", "title": "Availability tracking"}, {"id": "a67b660e-d74c-4cf3-bfc1-120c2b975314", "type": "concept", "title": "Conflict summaries"}, {"id": "eaa5cef5-82ea-4031-8183-19c2e6b5b3a8", "type": "concept", "title": "Confidential notes"}], "description": "Why learn it: Students practice keeping accurate, confidential records that support the director and production office."}, {"id": "e1101ccd-f93b-43ee-8322-df8675aa5918", "type": "subtopic", "title": "Ethical audition rooms", "children": [{"id": "6c648a5b-67f9-407e-887f-249ebc1e0045", "type": "concept", "title": "Equity of access"}, {"id": "6ec55eb7-b0fa-4981-ab95-4801b105247d", "type": "concept", "title": "Callback communication"}, {"id": "8988df85-9a7f-4495-8ea6-96ae02cbb4de", "type": "concept", "title": "Sensitive content notices"}, {"id": "e4d82891-b79d-4c2b-9b3a-5444b92ade00", "type": "concept", "title": "Confidentiality"}], "description": "Why learn it: The focus is on transparent process, consent-aware material use, and respectful handling of power dynamics."}]}, {"id": "b786ee83-53f2-43cb-a8f9-6092b573a8e3", "type": "topic", "title": "The Prompt Book", "description": "The prompt book is the stage manager's operating system for the production. Students learn to build a book that can support rehearsal, technical integration, show calling, substitutions, emergency response, and long-term show maintenance.", "children": [{"id": "3788733f-b220-49c3-8cfd-65c5d2fcca2f", "type": "subtopic", "title": "Prompt book architecture", "children": [{"id": "6bbc8726-63ff-483f-bd79-1494d2cc0fe8", "type": "concept", "title": "Script pages"}, {"id": "7a73f4f6-aa81-4fb4-8ccc-55858a803a43", "type": "concept", "title": "Contact sheets"}, {"id": "002769e9-fb1a-43e6-a802-6225c9b53913", "type": "concept", "title": "Calendars"}, {"id": "18473446-c88b-49f2-bf01-892fd0f7b25b", "type": "concept", "title": "Reports"}, {"id": "44c5e9e3-81e4-4ec2-a5ae-ee6df922c036", "type": "concept", "title": "Run sheets"}], "description": "Why learn it: Students design a book that stores essential information in a stable, findable structure."}, {"id": "46827a7f-1db2-42e7-bf92-de5aa550777d", "type": "subtopic", "title": "Version control", "children": [{"id": "44a89c66-bd7e-4459-bfd8-a62f4da74a25", "type": "concept", "title": "Page replacement"}, {"id": "9e9cf9cc-21ec-4618-86d1-a8c725449e46", "type": "concept", "title": "Date stamps"}, {"id": "af24874d-a52c-4a3d-bab7-4c93f84aeca3", "type": "concept", "title": "Change logs"}, {"id": "b1864c8d-2131-40a6-bef9-1a9bb0501030", "type": "concept", "title": "Digital backups"}], "description": "Why learn it: Students learn how to keep script revisions, blocking changes, design updates, and cue changes synchronized."}, {"id": "9ce9456a-2180-4b47-9ba6-8b77c9943f08", "type": "subtopic", "title": "Operational readiness", "children": [{"id": "26517fba-39cc-45de-9a68-31009a506eda", "type": "concept", "title": "Emergency contacts"}, {"id": "4a0985e8-f47d-4fda-b33f-6631fd17f950", "type": "concept", "title": "Understudy notes"}, {"id": "7755df85-9989-4e75-ba5d-d40b915230df", "type": "concept", "title": "Cue sequences"}, {"id": "515b094d-27a1-4ad7-8e2a-20220f6cbe97", "type": "concept", "title": "Shift plots"}], "description": "Why learn it: The prompt book becomes a tool for solving problems quickly under pressure."}]}, {"id": "ea0494f2-5536-48c8-9e9b-7635c9dfaa1a", "type": "topic", "title": "Blocking Notation and Staging Documentation", "description": "Blocking notation turns live staging into repeatable knowledge. Students learn systems for recording actor movement, entrances, exits, prop interactions, scene shifts, and spatial relationships with clarity and speed.", "children": [{"id": "e74af775-49e4-4e1d-aafd-324c3c31135e", "type": "subtopic", "title": "Notation systems", "children": [{"id": "173313df-1a5a-4526-936d-a612d92a4867", "type": "concept", "title": "Stage directions"}, {"id": "3e61bfef-505d-44aa-a6f9-af5bb366bf35", "type": "concept", "title": "Actor initials"}, {"id": "2e63bc74-e8dc-4ed2-9d10-a6c0628d0a99", "type": "concept", "title": "Traffic patterns"}, {"id": "cbdf7f06-5ad6-4f0c-ba79-8d0de2ee820d", "type": "concept", "title": "Spatial landmarks"}], "description": "Why learn it: Students compare shorthand, diagrams, ground plans, and digital tools for different rehearsal contexts."}, {"id": "25421de7-e48c-4e65-bcb2-bfe7ee9ba515", "type": "subtopic", "title": "Accuracy under rehearsal pressure", "children": [{"id": "98ce5a16-f98d-4485-b843-f45ed7dedd57", "type": "concept", "title": "Listening while writing"}, {"id": "295b88f9-d1c6-4bff-b2c5-ce7b5326f9ac", "type": "concept", "title": "Clarifying questions"}, {"id": "e60c9ac6-55d7-4e12-9bff-0945d2256977", "type": "concept", "title": "Revision marks"}, {"id": "808f02bc-8996-43e4-8f47-9c9f8ce2d6cf", "type": "concept", "title": "Backups after rehearsal"}], "description": "Why learn it: Students practice capturing choices quickly without disrupting the director or performers."}, {"id": "e80ab4da-6279-4cca-abf0-d1b30c6eb9e8", "type": "subtopic", "title": "Maintenance notes", "children": [{"id": "01458513-ae53-473f-8ef7-9bd51c763329", "type": "concept", "title": "Line-of-sight issues"}, {"id": "f0e5639c-a13f-423f-a767-f3eef11aec9a", "type": "concept", "title": "Spacing corrections"}, {"id": "7802fe31-54e3-4caf-8e6a-ba5d2edec825", "type": "concept", "title": "Prop handoffs"}, {"id": "dd4ecf61-e49a-49a4-aa4a-e72332229447", "type": "concept", "title": "Understudy transfer"}], "description": "Why learn it: Students learn how blocking records support consistency during the run."}]}, {"id": "78139e2e-1111-4c3d-93b0-1c8e78f7eeb4", "type": "topic", "title": "Running Rehearsals", "description": "This topic builds the daily habits that make rehearsal rooms productive and humane. Students learn to prepare the room, start on time, track needs, communicate notes, and keep the process moving through uncertainty.", "children": [{"id": "4534304a-8a9b-4a1c-9af6-d43d8b43f7dc", "type": "subtopic", "title": "Daily preparation", "children": [{"id": "568928f1-aef2-440d-a7f0-5d91f70600d0", "type": "concept", "title": "Room reset"}, {"id": "6d5864e7-8d60-44dd-a047-9c415aa5f12e", "type": "concept", "title": "Props and furniture"}, {"id": "de839e02-2206-4eec-90e9-b0a05d0c1985", "type": "concept", "title": "Schedules"}, {"id": "7ef36851-b73d-44ef-9a3e-e6843352079e", "type": "concept", "title": "Announcements"}], "description": "Why learn it: Students learn the routine work that makes the room ready before artists arrive."}, {"id": "2f5da38e-b888-4879-8de3-3923b99b7e59", "type": "subtopic", "title": "Rehearsal reports", "children": [{"id": "ed9874a0-ec0e-43bd-9c77-347bdb8f9090", "type": "concept", "title": "Attendance"}, {"id": "2d5e2893-845e-4325-9275-e0fbd91ae355", "type": "concept", "title": "Timing"}, {"id": "438025d5-f670-4824-b7d6-c2418b19d8c9", "type": "concept", "title": "Departmental notes"}, {"id": "18bab2a6-aae0-4a76-9140-6795bcca503d", "type": "concept", "title": "Next-day priorities"}], "description": "Why learn it: Students practice reporting what happened, what changed, and what departments need to know."}, {"id": "4cc627b0-fca1-4caa-b694-a6bb67315bbc", "type": "subtopic", "title": "Room facilitation", "children": [{"id": "c3ed3ecd-93a9-497c-8b4d-7a33f01b2e51", "type": "concept", "title": "Break timing"}, {"id": "78b18b6d-f21d-4cc3-a990-b60d9eecca6d", "type": "concept", "title": "Conflict awareness"}, {"id": "d4cae330-d6a9-49e2-89cd-21dcd0ec47a5", "type": "concept", "title": "Director support"}, {"id": "ac3c0334-95a0-48f0-a02f-9380553f8a47", "type": "concept", "title": "Actor questions"}], "description": "Why learn it: The focus is on balancing hospitality, momentum, discipline, and responsiveness."}]}, {"id": "e2bc6315-daaa-408e-a114-8aed5f4d8792", "type": "topic", "title": "Communication and Paperwork", "description": "Excellent stage management depends on clear, timely, audience-specific communication. This section trains students to create paperwork that is useful, consistent, and easy for other departments to act on.", "children": [{"id": "8885dbfe-5c79-44c8-8b26-e226a6e12e64", "type": "subtopic", "title": "Core paperwork", "children": [{"id": "f625dc55-0b02-4ab4-a845-05912977980b", "type": "concept", "title": "Contact sheet"}, {"id": "5852c7c5-53ad-4f40-989b-a0317b32027e", "type": "concept", "title": "Scene breakdown"}, {"id": "12f2fb90-0f2c-483d-8e50-af2291256adf", "type": "concept", "title": "Prop list"}, {"id": "eb283cb3-a4db-48c8-9a6d-0bd4bd36e660", "type": "concept", "title": "Costume tracking"}, {"id": "8f275087-ea45-43bb-b703-2b5fd88684ce", "type": "concept", "title": "Rehearsal report"}], "description": "Why learn it: Students build the standard documents expected in rehearsal and performance contexts."}, {"id": "6bb54cbd-6786-45a2-9d9b-6070337fd56b", "type": "subtopic", "title": "Communication channels", "children": [{"id": "6f28902c-ed4e-4c13-bc54-677300d167be", "type": "concept", "title": "Email etiquette"}, {"id": "326634d1-3cfd-452f-b5b0-72b611bba6d6", "type": "concept", "title": "Subject lines"}, {"id": "aad6359f-c4a2-498a-bb1d-522310d39ccc", "type": "concept", "title": "Distribution lists"}, {"id": "e6beac74-0625-420f-92b7-5978b6d1edac", "type": "concept", "title": "Response windows"}], "description": "Why learn it: Students learn which messages belong in email, reports, meetings, calls, shared drives, or urgent direct contact."}, {"id": "e824ef9f-cd2d-4d86-9b2b-a862608da198", "type": "subtopic", "title": "Digital tools", "children": [{"id": "06399a63-5f1e-45b1-91e6-67e52cd737d6", "type": "concept", "title": "Shared documents"}, {"id": "21cb467f-70c0-42f0-847e-7ed7f5e02253", "type": "concept", "title": "Calendar systems"}, {"id": "fb92ca82-fa30-46fe-abbe-8790bc41764e", "type": "concept", "title": "Cloud storage"}, {"id": "e1a5bdde-8f2f-44c2-a11e-69f83b758389", "type": "concept", "title": "Backup protocols"}], "description": "Why learn it: The goal is tool literacy without letting software substitute for judgment."}]}, {"id": "5bb634c4-362d-4558-862a-22560b126ea8", "type": "topic", "title": "Calling Cues", "description": "Cue calling is where documentation, listening, rhythm, and calm converge. Students learn to prepare calling scripts, communicate with booth and backstage teams, and call cues with precision under live performance conditions.", "children": [{"id": "5fd92243-c6b3-4268-8add-397b7b557bd6", "type": "subtopic", "title": "Cue types and notation", "children": [{"id": "0bab41a7-8747-44a9-8da8-b52f3c62f859", "type": "concept", "title": "Standby language"}, {"id": "89fea848-5cc2-4b49-a3e7-a566c8c973ad", "type": "concept", "title": "Warning calls"}, {"id": "22252c99-23f5-44b8-97b9-8515694287b0", "type": "concept", "title": "Go calls"}, {"id": "ee05f9ed-68aa-44b3-b978-80e7f4a2a568", "type": "concept", "title": "Cue lights"}], "description": "Why learn it: Students learn how lighting, sound, automation, deck, projection, followspot, and special effects cues are marked and sequenced."}, {"id": "781b7e8f-aa67-4a6e-bd19-c6d7e18f2afa", "type": "subtopic", "title": "Rhythm and timing", "children": [{"id": "eacee291-b919-46fd-a8db-c0de46aa3b8a", "type": "concept", "title": "Visual cues"}, {"id": "89a81cd2-0441-4216-9486-571cc34407d9", "type": "concept", "title": "Text cues"}, {"id": "7cbcd41e-72ae-475f-9ee0-f7fed80c828e", "type": "concept", "title": "Musical counts"}, {"id": "acd8aa24-7665-44be-891e-9b3b1ca3a6ac", "type": "concept", "title": "Contingency timing"}], "description": "Why learn it: Students practice listening to text, music, movement, and visual events to call cues in performance rhythm."}, {"id": "082c4cfd-0a5f-4cf5-b5e8-223aa10878bd", "type": "subtopic", "title": "Booth communication", "children": [{"id": "4b7d55d4-0fe3-4e9d-b1b5-f72095c0a6fe", "type": "concept", "title": "Headset protocol"}, {"id": "b7debc9a-22a1-4383-bc52-48f3a90b573b", "type": "concept", "title": "Quiet discipline"}, {"id": "dc0552c1-fefc-432b-8fe9-017f03e73a3c", "type": "concept", "title": "Error recovery"}, {"id": "0b916fb3-3da4-4750-a862-07459dcdd3a7", "type": "concept", "title": "Post-show notes"}], "description": "Why learn it: The emphasis is on concise, standardized language that keeps operators confident and synchronized."}]}, {"id": "30a91f5a-a19b-493c-b848-75c333b7e8fc", "type": "topic", "title": "Technical and Dress Rehearsals", "description": "Tech is the point where all production systems meet. Students learn to help the room move from exploration to repeatability while protecting safety, morale, time, and artistic clarity.", "children": [{"id": "9d719791-0a59-4c07-a620-437ef31e5310", "type": "subtopic", "title": "Tech structure", "children": [{"id": "d32f5f18-0323-4c6c-a8bd-478d26ba0aa3", "type": "concept", "title": "Cue-to-cue flow"}, {"id": "761d5bb1-2e78-4ea2-9b5e-956aecaace1f", "type": "concept", "title": "Ten-out-of-twelve rules"}, {"id": "3fff9fa9-41d7-4b70-9cc8-2a3782daa1d4", "type": "concept", "title": "Stop/start procedure"}, {"id": "a474733e-847b-431b-8da2-96497b0afb03", "type": "concept", "title": "Hold language"}], "description": "Why learn it: Students distinguish dry tech, cue-to-cue, spacing, dress rehearsals, previews, and opening protocols."}, {"id": "d47df35c-56cf-4ea7-8520-d352723f3a0d", "type": "subtopic", "title": "Department coordination", "children": [{"id": "ce4bc8e8-d0fe-422d-80d4-565c85704458", "type": "concept", "title": "Cue updates"}, {"id": "aeb152b8-9eeb-4f24-8a7a-0fe5634ea85c", "type": "concept", "title": "Scene shifts"}, {"id": "02ec9069-b244-4c36-888a-bf8b6dcc6f43", "type": "concept", "title": "Wardrobe needs"}, {"id": "35da49c0-efca-44a4-97ef-dc01e5b9e5af", "type": "concept", "title": "Sound checks"}], "description": "Why learn it: Students practice tracking questions and decisions across design and technical departments."}, {"id": "c287408a-f22f-4dd7-bfc6-8470c07c09e2", "type": "subtopic", "title": "Dress rehearsal standards", "children": [{"id": "f15e5da1-d6a7-410c-8a06-a872fbfff82d", "type": "concept", "title": "Performance conditions"}, {"id": "96211c9f-2c1f-4603-8564-3e134c834ef2", "type": "concept", "title": "Notes process"}, {"id": "89f7a153-fa4b-4191-ab5c-28f412ccc10b", "type": "concept", "title": "Pre-show checks"}, {"id": "0dd96f98-75de-4307-9e95-c6fdd9f0cef9", "type": "concept", "title": "Post-show reporting"}], "description": "Why learn it: The goal is to prepare for the first audience by integrating performance, design, backstage traffic, and timing."}]}, {"id": "8a5d680f-d2e4-4396-9ccb-00f96198f20e", "type": "topic", "title": "Running the Show and Maintaining Performance", "description": "Once a show opens, the stage manager becomes the guardian of consistency, safety, timing, and communication. Students learn how to maintain the production without freezing it or ignoring live performance realities.", "children": [{"id": "a0d7fa96-05d2-497a-b2e7-663219753d72", "type": "subtopic", "title": "Performance operations", "children": [{"id": "2d3ea29c-19ef-4c02-b2b7-fedd519cf8cf", "type": "concept", "title": "Sign-in"}, {"id": "cdc72069-e23d-4fff-8fa2-91a72bb00924", "type": "concept", "title": "House management contact"}, {"id": "db024d59-0301-4dfb-8a44-47da06251b3a", "type": "concept", "title": "Half-hour calls"}, {"id": "fe4bfb7f-cc20-4a7b-ba7f-b75cd239db9b", "type": "concept", "title": "Performance reports"}], "description": "Why learn it: Students learn pre-show, intermission, post-show, and emergency routines."}, {"id": "b7bd3b31-cbe5-48d9-8440-a8697eaa9959", "type": "subtopic", "title": "Show maintenance", "children": [{"id": "ff0b8ecd-910b-49e2-aecb-6fa9a52cabfe", "type": "concept", "title": "Brush-up notes"}, {"id": "36abe3da-49f3-485c-a726-7dfe4b8eb125", "type": "concept", "title": "Line notes"}, {"id": "7d1fdc25-5c37-40ed-a8bf-49ea571a7284", "type": "concept", "title": "Replacement rehearsals"}, {"id": "0ccf1051-1ca7-4a9b-8fc1-5ef5d2de34a6", "type": "concept", "title": "Quality checks"}], "description": "Why learn it: Students learn how to preserve staging, pacing, props, and cues over a run."}, {"id": "c16dbfde-5024-4f44-92b1-8373a2a47854", "type": "subtopic", "title": "Problem solving in performance", "children": [{"id": "016d34a6-32dd-49ea-a452-a8f1e2be227e", "type": "concept", "title": "Missed entrances"}, {"id": "a06d135d-0b4a-40fd-854e-86e7ae1109fd", "type": "concept", "title": "Technical failures"}, {"id": "491b132f-d4d9-462b-82aa-4e6c4d08d686", "type": "concept", "title": "Illness or injury"}, {"id": "689cbb01-c221-47f8-bb8f-d47a0e19f489", "type": "concept", "title": "Audience disruptions"}], "description": "Why learn it: Students practice calm decision-making when live conditions change."}]}, {"id": "bdbbdaf7-dc50-4aaf-b57f-f9b0b344150b", "type": "topic", "title": "Safety, Accessibility, Consent, and Intimacy Protocols", "description": "World-class stage management treats care as production infrastructure. Students learn practical protocols for reducing harm, supporting access, handling sensitive material, and knowing when to bring in qualified specialists.", "children": [{"id": "4306dead-4437-418f-bdd9-c3eb1e98b0f1", "type": "subtopic", "title": "Safety systems", "children": [{"id": "1423f56a-ebc9-4afb-bf1a-1174c5eab8ea", "type": "concept", "title": "Risk assessment"}, {"id": "169ca51e-24e6-48ea-8fdc-1c9adc1537c7", "type": "concept", "title": "Fight calls"}, {"id": "e8cdf316-e611-4437-a1e4-3dd358f6fa50", "type": "concept", "title": "First aid awareness"}, {"id": "2e9aafc4-68f2-4c50-bff9-e7a0643f88a0", "type": "concept", "title": "Incident reports"}], "description": "Why learn it: Students learn how to recognize hazards, document incidents, and support emergency response."}, {"id": "19ab1163-e6b3-41c9-aff2-2fde37544202", "type": "subtopic", "title": "Accessibility practice", "children": [{"id": "74a92c31-fee9-4472-ba92-c0fd9d91e706", "type": "concept", "title": "Access check-ins"}, {"id": "0e450319-6eee-4e44-a216-08b78026b505", "type": "concept", "title": "Communication preferences"}, {"id": "1d2b657b-2639-4462-bbf7-0a62b225d9ee", "type": "concept", "title": "Assistive technology"}, {"id": "d356e9fa-0e11-4634-bef3-10190eb2ad14", "type": "concept", "title": "Schedule transparency"}], "description": "Why learn it: Students consider access needs for performers, crew, staff, and audiences throughout rehearsal and performance."}, {"id": "d4e7c94a-896b-4404-ac92-ef8dfa7f2d83", "type": "subtopic", "title": "Consent and intimacy", "children": [{"id": "2018dd0e-caf8-4588-ab4b-7b3b84695662", "type": "concept", "title": "Closed-room protocols"}, {"id": "4e9f80ae-66ef-43d3-a9b1-acfb16c45298", "type": "concept", "title": "Boundary language"}, {"id": "ff548561-37af-4834-924a-74502533de82", "type": "concept", "title": "Documentation limits"}, {"id": "a1406552-55d7-412e-b728-7d26996fd82a", "type": "concept", "title": "Maintenance calls"}], "description": "Why learn it: Students learn the stage manager's support role in consent-based rooms while respecting the work of intimacy directors and fight/intimacy specialists."}]}, {"id": "900854a7-ce58-4e70-b6f8-4829c3ed1090", "type": "topic", "title": "Professional Standards, Unions, and Labor Ethics", "description": "This topic connects classroom practice to the realities of professional theater labor. Students learn the vocabulary of contracts, breaks, workplace standards, and ethical responsibility in union and non-union contexts.", "childr