insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('814a4eac-f47d-4114-8d53-8ee702f8ce8b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'The Stage Manager''s Role', 'This topic frames stage management as an artistic, logistical, ethical, and relational leadership practice. Students learn where authority comes from, where it stops, and how the stage manager protects the production process without taking over the creative process.', 0),
  ('95db7d62-23ff-4d1f-8eaf-f55192ae1e49', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '814a4eac-f47d-4114-8d53-8ee702f8ce8b', 'subtopic'::public.curated_course_node_type, 'Core responsibilities', 'Why learn it: Students identify what the stage manager owns before rehearsal, during rehearsal, in technical rehearsals, and during the run.', 0),
  ('a08cd802-1242-4bd6-93fb-b1e7921e65c7', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '95db7d62-23ff-4d1f-8eaf-f55192ae1e49', 'concept'::public.curated_course_node_type, 'Rehearsal room preparation', null, 0),
