  ('0e97f9b7-74ca-460f-b72a-893bff783ee8', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '95db7d62-23ff-4d1f-8eaf-f55192ae1e49', 'concept'::public.curated_course_node_type, 'Show maintenance', null, 3),
  ('d57d7308-c009-4fa0-8cde-79e8e8dad3df', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '814a4eac-f47d-4114-8d53-8ee702f8ce8b', 'subtopic'::public.curated_course_node_type, 'Leadership without authorship', 'Why learn it: The point is to practice leadership that serves the director''s vision, the ensemble''s process, and the production''s practical needs.', 1),
  ('68096938-111e-4ea9-aad5-3a688525df9c', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'd57d7308-c009-4fa0-8cde-79e8e8dad3df', 'concept'::public.curated_course_node_type, 'Facilitation vs. control', null, 0),
