  ('8468b030-05a4-4eff-80b6-3e86e125f8c2', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'd57d7308-c009-4fa0-8cde-79e8e8dad3df', 'concept'::public.curated_course_node_type, 'Boundary setting', null, 2),
  ('0be7c5bb-9b10-4711-9f7f-ffe36d5c4dd0', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'd57d7308-c009-4fa0-8cde-79e8e8dad3df', 'concept'::public.curated_course_node_type, 'Escalation paths', null, 3),
  ('9125e956-0235-4750-8e2d-a0316791cf02', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '814a4eac-f47d-4114-8d53-8ee702f8ce8b', 'subtopic'::public.curated_course_node_type, 'Professional identity', 'Why learn it: Students connect classroom habits to professional expectations so their work reads as reliable, calm, and clear.', 2),
  ('35c47a41-4195-466d-aeda-a08c19dea5aa', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9125e956-0235-4750-8e2d-a0316791cf02', 'concept'::public.curated_course_node_type, 'Punctuality', null, 0),
