  ('00c9da06-5631-4a37-844d-f7df4940120f', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9125e956-0235-4750-8e2d-a0316791cf02', 'concept'::public.curated_course_node_type, 'Consistency', null, 2),
  ('2cd5ae2e-2e03-4798-a741-6945f06cf427', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9125e956-0235-4750-8e2d-a0316791cf02', 'concept'::public.curated_course_node_type, 'Documentation habits', null, 3),
  ('92897fbd-bc7e-4eed-9eb5-e9ccd9a1ab8d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Production Structures and Collaboration', 'Stage managers must understand the full production ecosystem. This section builds fluency in who does what, how decisions move, and how a stage manager coordinates across artistic, technical, administrative, and front-of-house teams.', 1),
  ('bfc31d24-7eed-4736-9868-c1e582ef12ce', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '92897fbd-bc7e-4eed-9eb5-e9ccd9a1ab8d', 'subtopic'::public.curated_course_node_type, 'Production team roles', 'Why learn it: Students learn the responsibilities and decision rights of directors, designers, production managers, technical directors, department heads, performers, and crew.', 0),
  ('26d1430e-caad-4210-b40b-75120a62f823', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'bfc31d24-7eed-4736-9868-c1e582ef12ce', 'concept'::public.curated_course_node_type, 'Reporting lines', null, 0),
  ('ee4b062f-df6d-4ccf-b161-e879e8f66bbf', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'bfc31d24-7eed-4736-9868-c1e582ef12ce', 'concept'::public.curated_course_node_type, 'Design meetings', null, 1),
  ('f2e572a8-65ee-400c-b1c4-a29ecc6c4500', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'bfc31d24-7eed-4736-9868-c1e582ef12ce', 'concept'::public.curated_course_node_type, 'Departmental vocabulary', null, 2),
  ('24c80eb4-9bff-4398-a71b-eb9cc95b778b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'bfc31d24-7eed-4736-9868-c1e582ef12ce', 'concept'::public.curated_course_node_type, 'Role boundaries', null, 3),
  ('99877c45-27fd-4d6d-aa80-16b73744d2db', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '92897fbd-bc7e-4eed-9eb5-e9ccd9a1ab8d', 'subtopic'::public.curated_course_node_type, 'Production calendar logic', 'Why learn it: Students learn how institutional calendars shape rehearsal schedules, design deadlines, shop builds, tech, previews, opening, and strike.', 1),
  ('51e82fa7-f7cb-410f-a055-845e4fe89972', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '99877c45-27fd-4d6d-aa80-16b73744d2db', 'concept'::public.curated_course_node_type, 'Milestones', null, 0),
  ('0a43aca5-668e-4647-afa4-05acd1eb84f9', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '99877c45-27fd-4d6d-aa80-16b73744d2db', 'concept'::public.curated_course_node_type, 'Critical path', null, 1),
  ('a2294ddc-ea24-41ba-a3c7-842339e9f6c8', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '99877c45-27fd-4d6d-aa80-16b73744d2db', 'concept'::public.curated_course_node_type, 'Deadline dependencies', null, 2),
  ('2b8227af-467d-4fa0-ab13-d15ae1d29e88', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '99877c45-27fd-4d6d-aa80-16b73744d2db', 'concept'::public.curated_course_node_type, 'Conflict windows', null, 3),
  ('77a48ef5-b9f8-4080-8d65-7cb3e36d154d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '92897fbd-bc7e-4eed-9eb5-e9ccd9a1ab8d', 'subtopic'::public.curated_course_node_type, 'Meeting practice', 'Why learn it: The goal is to make meetings efficient, inclusive, and actionable rather than merely informational.', 2),
  ('b39b9afe-b05d-44e8-b4e7-b6df5bf25d69', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '77a48ef5-b9f8-4080-8d65-7cb3e36d154d', 'concept'::public.curated_course_node_type, 'Agendas', null, 0),
  ('2d48d908-7846-496e-83af-bfc0c4f97a3a', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '77a48ef5-b9f8-4080-8d65-7cb3e36d154d', 'concept'::public.curated_course_node_type, 'Minutes', null, 1),
  ('03be1718-6d39-48a2-9d34-27ad8e3ccfb4', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '77a48ef5-b9f8-4080-8d65-7cb3e36d154d', 'concept'::public.curated_course_node_type, 'Action items', null, 2),
  ('8a0c90eb-9cd1-410d-a56b-66c268a2883c', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '77a48ef5-b9f8-4080-8d65-7cb3e36d154d', 'concept'::public.curated_course_node_type, 'Follow-up tracking', null, 3),
  ('d3bfb64b-f07b-4333-af25-db50cb57bc21', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Auditions and Casting Support', 'This topic prepares stage managers to support auditions fairly and efficiently while respecting artistic authority and performer dignity. Students learn the paperwork, timing, room flow, and communication expected before casting is finalized.', 2),
  ('19776284-24c1-4aff-a5e1-5f5e2e12bec1', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'd3bfb64b-f07b-4333-af25-db50cb57bc21', 'subtopic'::public.curated_course_node_type, 'Audition logistics', 'Why learn it: Students plan audition spaces, materials, sign-in flow, timekeeping, and communication with auditioners.', 0),
  ('95267f10-3571-4c10-8c76-fdfba50bd225', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '19776284-24c1-4aff-a5e1-5f5e2e12bec1', 'concept'::public.curated_course_node_type, 'Room setup', null, 0),
  ('1f4132fd-0539-4772-9f45-402ddcc6af51', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '19776284-24c1-4aff-a5e1-5f5e2e12bec1', 'concept'::public.curated_course_node_type, 'Check-in systems', null, 1),
