  ('b96aa309-800a-433f-977e-00cc99d1d186', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '19776284-24c1-4aff-a5e1-5f5e2e12bec1', 'concept'::public.curated_course_node_type, 'Accessibility needs', null, 3),
