  ('f2d7c46d-8f90-4664-a781-62fc270e1216', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '855bdc4b-27b2-461f-9e70-c3d6d7bdb09d', 'concept'::public.curated_course_node_type, 'Audition forms', null, 0);
