  ('e4d82891-b79d-4c2b-9b3a-5444b92ade00', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e1101ccd-f93b-43ee-8322-df8675aa5918', 'concept'::public.curated_course_node_type, 'Confidentiality', null, 3),
  ('b786ee83-53f2-43cb-a8f9-6092b573a8e3', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'The Prompt Book', 'The prompt book is the stage manager''s operating system for the production. Students learn to build a book that can support rehearsal, technical integration, show calling, substitutions, emergency response, and long-term show maintenance.', 3),
  ('3788733f-b220-49c3-8cfd-65c5d2fcca2f', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'b786ee83-53f2-43cb-a8f9-6092b573a8e3', 'subtopic'::public.curated_course_node_type, 'Prompt book architecture', 'Why learn it: Students design a book that stores essential information in a stable, findable structure.', 0),
