  ('44c5e9e3-81e4-4ec2-a5ae-ee6df922c036', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '3788733f-b220-49c3-8cfd-65c5d2fcca2f', 'concept'::public.curated_course_node_type, 'Run sheets', null, 4),
  ('46827a7f-1db2-42e7-bf92-de5aa550777d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'b786ee83-53f2-43cb-a8f9-6092b573a8e3', 'subtopic'::public.curated_course_node_type, 'Version control', 'Why learn it: Students learn how to keep script revisions, blocking changes, design updates, and cue changes synchronized.', 1),
