  ('b1864c8d-2131-40a6-bef9-1a9bb0501030', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '46827a7f-1db2-42e7-bf92-de5aa550777d', 'concept'::public.curated_course_node_type, 'Digital backups', null, 3),
