  ('26517fba-39cc-45de-9a68-31009a506eda', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9ce9456a-2180-4b47-9ba6-8b77c9943f08', 'concept'::public.curated_course_node_type, 'Emergency contacts', null, 0),
