  ('7755df85-9989-4e75-ba5d-d40b915230df', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9ce9456a-2180-4b47-9ba6-8b77c9943f08', 'concept'::public.curated_course_node_type, 'Cue sequences', null, 2),
  ('515b094d-27a1-4ad7-8e2a-20220f6cbe97', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9ce9456a-2180-4b47-9ba6-8b77c9943f08', 'concept'::public.curated_course_node_type, 'Shift plots', null, 3),
  ('ea0494f2-5536-48c8-9e9b-7635c9dfaa1a', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Blocking Notation and Staging Documentation', 'Blocking notation turns live staging into repeatable knowledge. Students learn systems for recording actor movement, entrances, exits, prop interactions, scene shifts, and spatial relationships with clarity and speed.', 4),
  ('e74af775-49e4-4e1d-aafd-324c3c31135e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'ea0494f2-5536-48c8-9e9b-7635c9dfaa1a', 'subtopic'::public.curated_course_node_type, 'Notation systems', 'Why learn it: Students compare shorthand, diagrams, ground plans, and digital tools for different rehearsal contexts.', 0),
  ('173313df-1a5a-4526-936d-a612d92a4867', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e74af775-49e4-4e1d-aafd-324c3c31135e', 'concept'::public.curated_course_node_type, 'Stage directions', null, 0),
  ('3e61bfef-505d-44aa-a6f9-af5bb366bf35', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e74af775-49e4-4e1d-aafd-324c3c31135e', 'concept'::public.curated_course_node_type, 'Actor initials', null, 1),
  ('2e63bc74-e8dc-4ed2-9d10-a6c0628d0a99', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e74af775-49e4-4e1d-aafd-324c3c31135e', 'concept'::public.curated_course_node_type, 'Traffic patterns', null, 2),
  ('cbdf7f06-5ad6-4f0c-ba79-8d0de2ee820d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e74af775-49e4-4e1d-aafd-324c3c31135e', 'concept'::public.curated_course_node_type, 'Spatial landmarks', null, 3),
  ('25421de7-e48c-4e65-bcb2-bfe7ee9ba515', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'ea0494f2-5536-48c8-9e9b-7635c9dfaa1a', 'subtopic'::public.curated_course_node_type, 'Accuracy under rehearsal pressure', 'Why learn it: Students practice capturing choices quickly without disrupting the director or performers.', 1),
  ('98ce5a16-f98d-4485-b843-f45ed7dedd57', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '25421de7-e48c-4e65-bcb2-bfe7ee9ba515', 'concept'::public.curated_course_node_type, 'Listening while writing', null, 0),
  ('295b88f9-d1c6-4bff-b2c5-ce7b5326f9ac', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '25421de7-e48c-4e65-bcb2-bfe7ee9ba515', 'concept'::public.curated_course_node_type, 'Clarifying questions', null, 1),
  ('e60c9ac6-55d7-4e12-9bff-0945d2256977', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '25421de7-e48c-4e65-bcb2-bfe7ee9ba515', 'concept'::public.curated_course_node_type, 'Revision marks', null, 2),
  ('808f02bc-8996-43e4-8f47-9c9f8ce2d6cf', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '25421de7-e48c-4e65-bcb2-bfe7ee9ba515', 'concept'::public.curated_course_node_type, 'Backups after rehearsal', null, 3),
  ('e80ab4da-6279-4cca-abf0-d1b30c6eb9e8', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'ea0494f2-5536-48c8-9e9b-7635c9dfaa1a', 'subtopic'::public.curated_course_node_type, 'Maintenance notes', 'Why learn it: Students learn how blocking records support consistency during the run.', 2),
  ('01458513-ae53-473f-8ef7-9bd51c763329', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e80ab4da-6279-4cca-abf0-d1b30c6eb9e8', 'concept'::public.curated_course_node_type, 'Line-of-sight issues', null, 0),
  ('f0e5639c-a13f-423f-a767-f3eef11aec9a', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e80ab4da-6279-4cca-abf0-d1b30c6eb9e8', 'concept'::public.curated_course_node_type, 'Spacing corrections', null, 1),
  ('7802fe31-54e3-4caf-8e6a-ba5d2edec825', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e80ab4da-6279-4cca-abf0-d1b30c6eb9e8', 'concept'::public.curated_course_node_type, 'Prop handoffs', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('dd4ecf61-e49a-49a4-aa4a-e72332229447', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e80ab4da-6279-4cca-abf0-d1b30c6eb9e8', 'concept'::public.curated_course_node_type, 'Understudy transfer', null, 3),
  ('78139e2e-1111-4c3d-93b0-1c8e78f7eeb4', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Running Rehearsals', 'This topic builds the daily habits that make rehearsal rooms productive and humane. Students learn to prepare the room, start on time, track needs, communicate notes, and keep the process moving through uncertainty.', 5),
  ('4534304a-8a9b-4a1c-9af6-d43d8b43f7dc', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '78139e2e-1111-4c3d-93b0-1c8e78f7eeb4', 'subtopic'::public.curated_course_node_type, 'Daily preparation', 'Why learn it: Students learn the routine work that makes the room ready before artists arrive.', 0),
  ('568928f1-aef2-440d-a7f0-5d91f70600d0', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4534304a-8a9b-4a1c-9af6-d43d8b43f7dc', 'concept'::public.curated_course_node_type, 'Room reset', null, 0),
  ('6d5864e7-8d60-44dd-a047-9c415aa5f12e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4534304a-8a9b-4a1c-9af6-d43d8b43f7dc', 'concept'::public.curated_course_node_type, 'Props and furniture', null, 1),
  ('de839e02-2206-4eec-90e9-b0a05d0c1985', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4534304a-8a9b-4a1c-9af6-d43d8b43f7dc', 'concept'::public.curated_course_node_type, 'Schedules', null, 2),
  ('7ef36851-b73d-44ef-9a3e-e6843352079e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4534304a-8a9b-4a1c-9af6-d43d8b43f7dc', 'concept'::public.curated_course_node_type, 'Announcements', null, 3),
  ('2f5da38e-b888-4879-8de3-3923b99b7e59', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '78139e2e-1111-4c3d-93b0-1c8e78f7eeb4', 'subtopic'::public.curated_course_node_type, 'Rehearsal reports', 'Why learn it: Students practice reporting what happened, what changed, and what departments need to know.', 1),
  ('ed9874a0-ec0e-43bd-9c77-347bdb8f9090', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '2f5da38e-b888-4879-8de3-3923b99b7e59', 'concept'::public.curated_course_node_type, 'Attendance', null, 0),
  ('2d5e2893-845e-4325-9275-e0fbd91ae355', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '2f5da38e-b888-4879-8de3-3923b99b7e59', 'concept'::public.curated_course_node_type, 'Timing', null, 1),
  ('438025d5-f670-4824-b7d6-c2418b19d8c9', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '2f5da38e-b888-4879-8de3-3923b99b7e59', 'concept'::public.curated_course_node_type, 'Departmental notes', null, 2),
  ('18bab2a6-aae0-4a76-9140-6795bcca503d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '2f5da38e-b888-4879-8de3-3923b99b7e59', 'concept'::public.curated_course_node_type, 'Next-day priorities', null, 3),
  ('4cc627b0-fca1-4caa-b694-a6bb67315bbc', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '78139e2e-1111-4c3d-93b0-1c8e78f7eeb4', 'subtopic'::public.curated_course_node_type, 'Room facilitation', 'Why learn it: The focus is on balancing hospitality, momentum, discipline, and responsiveness.', 2),
  ('c3ed3ecd-93a9-497c-8b4d-7a33f01b2e51', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4cc627b0-fca1-4caa-b694-a6bb67315bbc', 'concept'::public.curated_course_node_type, 'Break timing', null, 0),
  ('78b18b6d-f21d-4cc3-a990-b60d9eecca6d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4cc627b0-fca1-4caa-b694-a6bb67315bbc', 'concept'::public.curated_course_node_type, 'Conflict awareness', null, 1),
  ('d4cae330-d6a9-49e2-89cd-21dcd0ec47a5', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4cc627b0-fca1-4caa-b694-a6bb67315bbc', 'concept'::public.curated_course_node_type, 'Director support', null, 2),
  ('ac3c0334-95a0-48f0-a02f-9380553f8a47', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4cc627b0-fca1-4caa-b694-a6bb67315bbc', 'concept'::public.curated_course_node_type, 'Actor questions', null, 3),
  ('e2bc6315-daaa-408e-a114-8aed5f4d8792', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Communication and Paperwork', 'Excellent stage management depends on clear, timely, audience-specific communication. This section trains students to create paperwork that is useful, consistent, and easy for other departments to act on.', 6),
  ('8885dbfe-5c79-44c8-8b26-e226a6e12e64', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e2bc6315-daaa-408e-a114-8aed5f4d8792', 'subtopic'::public.curated_course_node_type, 'Core paperwork', 'Why learn it: Students build the standard documents expected in rehearsal and performance contexts.', 0),
  ('f625dc55-0b02-4ab4-a845-05912977980b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '8885dbfe-5c79-44c8-8b26-e226a6e12e64', 'concept'::public.curated_course_node_type, 'Contact sheet', null, 0),
  ('5852c7c5-53ad-4f40-989b-a0317b32027e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '8885dbfe-5c79-44c8-8b26-e226a6e12e64', 'concept'::public.curated_course_node_type, 'Scene breakdown', null, 1),
  ('12f2fb90-0f2c-483d-8e50-af2291256adf', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '8885dbfe-5c79-44c8-8b26-e226a6e12e64', 'concept'::public.curated_course_node_type, 'Prop list', null, 2),
  ('eb283cb3-a4db-48c8-9a6d-0bd4bd36e660', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '8885dbfe-5c79-44c8-8b26-e226a6e12e64', 'concept'::public.curated_course_node_type, 'Costume tracking', null, 3),
  ('8f275087-ea45-43bb-b703-2b5fd88684ce', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '8885dbfe-5c79-44c8-8b26-e226a6e12e64', 'concept'::public.curated_course_node_type, 'Rehearsal report', null, 4),
  ('6bb54cbd-6786-45a2-9d9b-6070337fd56b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e2bc6315-daaa-408e-a114-8aed5f4d8792', 'subtopic'::public.curated_course_node_type, 'Communication channels', 'Why learn it: Students learn which messages belong in email, reports, meetings, calls, shared drives, or urgent direct contact.', 1),
  ('6f28902c-ed4e-4c13-bc54-677300d167be', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '6bb54cbd-6786-45a2-9d9b-6070337fd56b', 'concept'::public.curated_course_node_type, 'Email etiquette', null, 0),
  ('326634d1-3cfd-452f-b5b0-72b611bba6d6', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '6bb54cbd-6786-45a2-9d9b-6070337fd56b', 'concept'::public.curated_course_node_type, 'Subject lines', null, 1),
  ('aad6359f-c4a2-498a-bb1d-522310d39ccc', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '6bb54cbd-6786-45a2-9d9b-6070337fd56b', 'concept'::public.curated_course_node_type, 'Distribution lists', null, 2),
  ('e6beac74-0625-420f-92b7-5978b6d1edac', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '6bb54cbd-6786-45a2-9d9b-6070337fd56b', 'concept'::public.curated_course_node_type, 'Response windows', null, 3),
  ('e824ef9f-cd2d-4d86-9b2b-a862608da198', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e2bc6315-daaa-408e-a114-8aed5f4d8792', 'subtopic'::public.curated_course_node_type, 'Digital tools', 'Why learn it: The goal is tool literacy without letting software substitute for judgment.', 2),
  ('06399a63-5f1e-45b1-91e6-67e52cd737d6', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e824ef9f-cd2d-4d86-9b2b-a862608da198', 'concept'::public.curated_course_node_type, 'Shared documents', null, 0),
  ('21cb467f-70c0-42f0-847e-7ed7f5e02253', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e824ef9f-cd2d-4d86-9b2b-a862608da198', 'concept'::public.curated_course_node_type, 'Calendar systems', null, 1),
  ('fb92ca82-fa30-46fe-abbe-8790bc41764e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e824ef9f-cd2d-4d86-9b2b-a862608da198', 'concept'::public.curated_course_node_type, 'Cloud storage', null, 2),
  ('e1a5bdde-8f2f-44c2-a11e-69f83b758389', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'e824ef9f-cd2d-4d86-9b2b-a862608da198', 'concept'::public.curated_course_node_type, 'Backup protocols', null, 3),
  ('5bb634c4-362d-4558-862a-22560b126ea8', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Calling Cues', 'Cue calling is where documentation, listening, rhythm, and calm converge. Students learn to prepare calling scripts, communicate with booth and backstage teams, and call cues with precision under live performance conditions.', 7),
  ('5fd92243-c6b3-4268-8add-397b7b557bd6', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5bb634c4-362d-4558-862a-22560b126ea8', 'subtopic'::public.curated_course_node_type, 'Cue types and notation', 'Why learn it: Students learn how lighting, sound, automation, deck, projection, followspot, and special effects cues are marked and sequenced.', 0),
  ('0bab41a7-8747-44a9-8da8-b52f3c62f859', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5fd92243-c6b3-4268-8add-397b7b557bd6', 'concept'::public.curated_course_node_type, 'Standby language', null, 0),
  ('89fea848-5cc2-4b49-a3e7-a566c8c973ad', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5fd92243-c6b3-4268-8add-397b7b557bd6', 'concept'::public.curated_course_node_type, 'Warning calls', null, 1),
  ('22252c99-23f5-44b8-97b9-8515694287b0', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5fd92243-c6b3-4268-8add-397b7b557bd6', 'concept'::public.curated_course_node_type, 'Go calls', null, 2),
  ('ee05f9ed-68aa-44b3-b978-80e7f4a2a568', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5fd92243-c6b3-4268-8add-397b7b557bd6', 'concept'::public.curated_course_node_type, 'Cue lights', null, 3);
