values
  ('781b7e8f-aa67-4a6e-bd19-c6d7e18f2afa', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5bb634c4-362d-4558-862a-22560b126ea8', 'subtopic'::public.curated_course_node_type, 'Rhythm and timing', 'Why learn it: Students practice listening to text, music, movement, and visual events to call cues in performance rhythm.', 1),
  ('eacee291-b919-46fd-a8db-c0de46aa3b8a', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '781b7e8f-aa67-4a6e-bd19-c6d7e18f2afa', 'concept'::public.curated_course_node_type, 'Visual cues', null, 0),
