  ('7cbcd41e-72ae-475f-9ee0-f7fed80c828e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '781b7e8f-aa67-4a6e-bd19-c6d7e18f2afa', 'concept'::public.curated_course_node_type, 'Musical counts', null, 2),
  ('acd8aa24-7665-44be-891e-9b3b1ca3a6ac', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '781b7e8f-aa67-4a6e-bd19-c6d7e18f2afa', 'concept'::public.curated_course_node_type, 'Contingency timing', null, 3),
  ('082c4cfd-0a5f-4cf5-b5e8-223aa10878bd', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '5bb634c4-362d-4558-862a-22560b126ea8', 'subtopic'::public.curated_course_node_type, 'Booth communication', 'Why learn it: The emphasis is on concise, standardized language that keeps operators confident and synchronized.', 2),
  ('4b7d55d4-0fe3-4e9d-b1b5-f72095c0a6fe', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '082c4cfd-0a5f-4cf5-b5e8-223aa10878bd', 'concept'::public.curated_course_node_type, 'Headset protocol', null, 0),
  ('b7debc9a-22a1-4383-bc52-48f3a90b573b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '082c4cfd-0a5f-4cf5-b5e8-223aa10878bd', 'concept'::public.curated_course_node_type, 'Quiet discipline', null, 1),
  ('dc0552c1-fefc-432b-8fe9-017f03e73a3c', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '082c4cfd-0a5f-4cf5-b5e8-223aa10878bd', 'concept'::public.curated_course_node_type, 'Error recovery', null, 2),
  ('0b916fb3-3da4-4750-a862-07459dcdd3a7', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '082c4cfd-0a5f-4cf5-b5e8-223aa10878bd', 'concept'::public.curated_course_node_type, 'Post-show notes', null, 3),
  ('30a91f5a-a19b-493c-b848-75c333b7e8fc', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Technical and Dress Rehearsals', 'Tech is the point where all production systems meet. Students learn to help the room move from exploration to repeatability while protecting safety, morale, time, and artistic clarity.', 8),
  ('9d719791-0a59-4c07-a620-437ef31e5310', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '30a91f5a-a19b-493c-b848-75c333b7e8fc', 'subtopic'::public.curated_course_node_type, 'Tech structure', 'Why learn it: Students distinguish dry tech, cue-to-cue, spacing, dress rehearsals, previews, and opening protocols.', 0),
  ('d32f5f18-0323-4c6c-a8bd-478d26ba0aa3', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '9d719791-0a59-4c07-a620-437ef31e5310', 'concept'::public.curated_course_node_type, 'Cue-to-cue flow', null, 0),
