  ('f15e5da1-d6a7-410c-8a06-a872fbfff82d', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'c287408a-f22f-4dd7-bfc6-8470c07c09e2', 'concept'::public.curated_course_node_type, 'Performance conditions', null, 0),
