  ('89f7a153-fa4b-4191-ab5c-28f412ccc10b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'c287408a-f22f-4dd7-bfc6-8470c07c09e2', 'concept'::public.curated_course_node_type, 'Pre-show checks', null, 2),
  ('0dd96f98-75de-4307-9e95-c6fdd9f0cef9', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'c287408a-f22f-4dd7-bfc6-8470c07c09e2', 'concept'::public.curated_course_node_type, 'Post-show reporting', null, 3),
  ('8a5d680f-d2e4-4396-9ccb-00f96198f20e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Running the Show and Maintaining Performance', 'Once a show opens, the stage manager becomes the guardian of consistency, safety, timing, and communication. Students learn how to maintain the production without freezing it or ignoring live performance realities.', 9),
  ('a0d7fa96-05d2-497a-b2e7-663219753d72', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '8a5d680f-d2e4-4396-9ccb-00f96198f20e', 'subtopic'::public.curated_course_node_type, 'Performance operations', 'Why learn it: Students learn pre-show, intermission, post-show, and emergency routines.', 0),
  ('2d3ea29c-19ef-4c02-b2b7-fedd519cf8cf', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'a0d7fa96-05d2-497a-b2e7-663219753d72', 'concept'::public.curated_course_node_type, 'Sign-in', null, 0),
