  ('ff0b8ecd-910b-49e2-aecb-6fa9a52cabfe', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'b7bd3b31-cbe5-48d9-8440-a8697eaa9959', 'concept'::public.curated_course_node_type, 'Brush-up notes', null, 0),
