  ('016d34a6-32dd-49ea-a452-a8f1e2be227e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'c16dbfde-5024-4f44-92b1-8373a2a47854', 'concept'::public.curated_course_node_type, 'Missed entrances', null, 0),
