  ('bdbbdaf7-dc50-4aaf-b57f-f9b0b344150b', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Safety, Accessibility, Consent, and Intimacy Protocols', 'World-class stage management treats care as production infrastructure. Students learn practical protocols for reducing harm, supporting access, handling sensitive material, and knowing when to bring in qualified specialists.', 10),
