  ('1423f56a-ebc9-4afb-bf1a-1174c5eab8ea', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '4306dead-4437-418f-bdd9-c3eb1e98b0f1', 'concept'::public.curated_course_node_type, 'Risk assessment', null, 0),
