  ('19ab1163-e6b3-41c9-aff2-2fde37544202', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'bdbbdaf7-dc50-4aaf-b57f-f9b0b344150b', 'subtopic'::public.curated_course_node_type, 'Accessibility practice', 'Why learn it: Students consider access needs for performers, crew, staff, and audiences throughout rehearsal and performance.', 1),
  ('74a92c31-fee9-4472-ba92-c0fd9d91e706', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '19ab1163-e6b3-41c9-aff2-2fde37544202', 'concept'::public.curated_course_node_type, 'Access check-ins', null, 0),
