  ('d356e9fa-0e11-4634-bef3-10190eb2ad14', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '19ab1163-e6b3-41c9-aff2-2fde37544202', 'concept'::public.curated_course_node_type, 'Schedule transparency', null, 3),
