  ('2018dd0e-caf8-4588-ab4b-7b3b84695662', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'd4e7c94a-896b-4404-ac92-ef8dfa7f2d83', 'concept'::public.curated_course_node_type, 'Closed-room protocols', null, 0),
