  ('a1406552-55d7-412e-b728-7d26996fd82a', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', 'd4e7c94a-896b-4404-ac92-ef8dfa7f2d83', 'concept'::public.curated_course_node_type, 'Maintenance calls', null, 3),
  ('900854a7-ce58-4e70-b6f8-4829c3ed1090', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Professional Standards, Unions, and Labor Ethics', 'This topic connects classroom practice to the realities of professional theater labor. Students learn the vocabulary of contracts, breaks, workplace standards, and ethical responsibility in union and non-union contexts.', 11),
  ('3833e461-eb4e-44e4-8d92-af6e73d561ae', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '900854a7-ce58-4e70-b6f8-4829c3ed1090', 'subtopic'::public.curated_course_node_type, 'Actors'' Equity context', 'Why learn it: Students gain a practical overview of union expectations relevant to rehearsal, performance, safety, and communication.', 0),
  ('86e3f1bf-9c52-4a41-b2a5-271fb2d30a5c', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '3833e461-eb4e-44e4-8d92-af6e73d561ae', 'concept'::public.curated_course_node_type, 'Breaks', null, 0),
