  ('e6de320d-3129-44c7-b6d9-3775b266f4f9', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '3833e461-eb4e-44e4-8d92-af6e73d561ae', 'concept'::public.curated_course_node_type, 'Calls', null, 2),
  ('88e6df01-6a9f-4670-95bb-462363d42f50', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '3833e461-eb4e-44e4-8d92-af6e73d561ae', 'concept'::public.curated_course_node_type, 'Rulebooks', null, 3),
  ('4765212c-f3ce-4b94-bc31-43dac8caddcf', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '900854a7-ce58-4e70-b6f8-4829c3ed1090', 'subtopic'::public.curated_course_node_type, 'Labor ethics', 'Why learn it: Students examine how scheduling, unpaid labor, emotional labor, and power dynamics affect production culture.', 1),
