  ('43213621-6b65-4707-8d7b-e4dffe9afa5e', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '900854a7-ce58-4e70-b6f8-4829c3ed1090', 'subtopic'::public.curated_course_node_type, 'Professional paperwork', 'Why learn it: The goal is to prepare students for internships, assistantships, and entry-level stage management work.', 2),
  ('c3af5ec1-da8a-4e49-b9d5-165df7a9bfb5', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '43213621-6b65-4707-8d7b-e4dffe9afa5e', 'concept'::public.curated_course_node_type, 'Resume language', null, 0),
