  ('6c783536-d229-40fa-a0fd-763bc2d7ea24', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', '43213621-6b65-4707-8d7b-e4dffe9afa5e', 'concept'::public.curated_course_node_type, 'References', null, 2),
