  ('5c684b9f-2488-439d-91f0-599ed7eb4d47', 'c1d2e3f4-5a6b-4c31-8e01-1f2a3b4c5d31', null, 'topic'::public.curated_course_node_type, 'Inclusive Production Culture and Conflict Navigation', 'Stage managers often notice tension before anyone else does. This section teaches students to build trust, communicate across difference, and respond to conflict with clarity, humility, and appropriate escalation.', 12),
